class WP_Term { public $term_id; public $slug; public $name; public function __construct( $id, $slug, $name ) { $this->term_id=$id; $this->slug=$slug; $this->name=$name; } }
function absint( $v ) { return abs( (int) $v ); }
function is_wp_error( $v ) { return false; }
function sanitize_title( $v ) { return strtolower( preg_replace( '/[^a-zA-Z0-9-]/', '', $v ) ); }
